// The JXA build (FR-43): each mini/ts entry compiled on its own with mini/ts/jxa.d.ts, so every
// entry keeps its own global run(), to mini/js/<name>.js under a generated header. Page programs
// (FR-58), mini/ts/page/<name>.ts, are one function page typed against the DOM, built to
// mini/js/page/<name>.js as that function in parentheses for mini/lib/opencli.zsh's page_js.
import * as fs from "node:fs";
import * as path from "node:path";
import ts from "typescript";

export const HEADER = (name: string) =>
  `// Generated by .github/jxa.ts from mini/ts/${name}.ts; do not edit (npm run jxa:write).\n`;

const OPTIONS: ts.CompilerOptions = {
  target: ts.ScriptTarget.ES2020,
  lib: ["lib.es2020.d.ts"],
  types: [],
  strict: true,
  noUnusedLocals: true,
  noUnusedParameters: true,
  erasableSyntaxOnly: true,
  newLine: ts.NewLineKind.LineFeed,
  noEmitOnError: true,
};

const PAGE_OPTIONS: ts.CompilerOptions = {
  ...OPTIONS,
  lib: ["lib.es2020.d.ts", "lib.dom.d.ts"],
  removeComments: true,
};

const ONE_PAGE = "a page program is one top-level function page and nothing else";

function listTs(root: string, dir: string): string[] {
  const at = path.join(root, dir);
  if (!fs.existsSync(at)) return [];
  return fs
    .readdirSync(at, { withFileTypes: true })
    .filter((e) => e.isFile() && e.name.endsWith(".ts") && !e.name.endsWith(".d.ts"))
    .map((e) => `${dir}/${e.name}`)
    .sort();
}

// Top-level mini/ts/*.ts but the declarations, as repo paths.
export function entries(root: string): string[] {
  return listTs(root, "mini/ts");
}

// mini/ts/page/*.ts, as repo paths.
export function pages(root: string): string[] {
  return listTs(root, "mini/ts/page");
}

function hasRun(source: ts.SourceFile): boolean {
  return source.statements.some(
    (s) => ts.isFunctionDeclaration(s) && s.name?.text === "run" && s.body !== undefined,
  );
}

function onePage(source: ts.SourceFile): boolean {
  const [only, ...rest] = source.statements;
  return (
    rest.length === 0 &&
    only !== undefined &&
    ts.isFunctionDeclaration(only) &&
    only.name?.text === "page" &&
    only.body !== undefined &&
    !only.modifiers?.length
  );
}

function diagnostic(root: string, d: ts.Diagnostic): string {
  const text = ts.flattenDiagnosticMessageText(d.messageText, "\n");
  if (!d.file || d.start === undefined) return `error TS${d.code}: ${text}`;
  const { line, character } = d.file.getLineAndCharacterOfPosition(d.start);
  const file = path.relative(root, d.file.fileName);
  return `${file}(${line + 1},${character + 1}): error TS${d.code}: ${text}`;
}

// The lib files are the same for every entry: parse them once.
function cachedHost(options: ts.CompilerOptions): ts.CompilerHost {
  const host = ts.createCompilerHost(options);
  const cache = new Map<string, ts.SourceFile | undefined>();
  const getSourceFile = host.getSourceFile.bind(host);
  host.getSourceFile = (file, ...rest) => {
    if (!file.includes(`${path.sep}typescript${path.sep}lib${path.sep}`)) {
      return getSourceFile(file, ...rest);
    }
    if (!cache.has(file)) cache.set(file, getSourceFile(file, ...rest));
    return cache.get(file);
  };
  return host;
}

type Kind = {
  options: ts.CompilerOptions;
  roots: (file: string) => string[];
  shape: (source: ts.SourceFile, entry: string) => string[];
  output: (entry: string, text: string) => [string, string];
};

function compile(root: string, list: string[], kind: Kind, out: Map<string, string>): string[] {
  const errors: string[] = [];
  const host = cachedHost(kind.options);
  for (const entry of list) {
    const file = path.join(root, entry);
    const program = ts.createProgram({ rootNames: kind.roots(file), options: kind.options, host });
    const source = program.getSourceFile(file);
    if (!source) {
      errors.push(`${entry}: cannot read`);
      continue;
    }
    const before = errors.length;
    errors.push(...kind.shape(source, entry));
    for (const d of ts.getPreEmitDiagnostics(program)) errors.push(diagnostic(root, d));
    if (errors.length > before) continue;
    program.emit(source, (name, text) => {
      if (name.endsWith(".js")) out.set(...kind.output(entry, text));
    });
  }
  return errors;
}

// Every entry's mini/js text, keyed by repo path, or the errors that stop the build.
export function build(root: string): { outputs: Map<string, string>; errors: string[] } {
  const outputs = new Map<string, string>();
  const dts = path.join(root, "mini/ts/jxa.d.ts");
  const jxa: Kind = {
    options: OPTIONS,
    roots: (file) => [file, dts],
    shape: (source, entry) => [
      ...(ts.isExternalModule(source)
        ? [`${entry}: a JXA entry is a standalone script; no import or export`]
        : []),
      ...(hasRun(source) ? [] : [`${entry}: no top-level function run`]),
    ],
    output: (entry, text) => {
      const name = path.basename(entry, ".ts");
      return [`mini/js/${name}.js`, HEADER(name) + text];
    },
  };
  const page: Kind = {
    options: PAGE_OPTIONS,
    roots: (file) => [file],
    shape: (source, entry) => (onePage(source) ? [] : [`${entry}: ${ONE_PAGE}`]),
    output: (entry, text) => {
      const name = `page/${path.basename(entry, ".ts")}`;
      // The script's "use strict" would make the file two statements, not one expression.
      const code = text.replace(/^"use strict";\n/, "").trimEnd();
      return [`mini/js/${name}.js`, `${HEADER(name)}(${code})\n`];
    },
  };
  const errors = [
    ...compile(root, entries(root), jxa, outputs),
    ...compile(root, pages(root), page, outputs),
  ];
  return { outputs, errors };
}

// What differs between mini/js and the build: changed, missing and source-less files.
export function drift(root: string, outputs: Map<string, string>): string[] {
  const found: string[] = [];
  for (const [file, text] of outputs) {
    const at = path.join(root, file);
    if (!fs.existsSync(at)) found.push(`${file} is missing; run npm run jxa:write`);
    else if (fs.readFileSync(at, "utf8") !== text) {
      found.push(`${file} differs from tsc output; run npm run jxa:write`);
    }
  }
  for (const file of orphans(root, outputs)) {
    found.push(`${file} has no source ${file.replace(/^mini\/js\//, "mini/ts/").slice(0, -3)}.ts`);
  }
  return found;
}

// Generated-looking files without a source: regular *.js files directly in mini/js or
// mini/js/page. Anything else there (another directory, .DS_Store) is not this build's.
export function orphans(root: string, outputs: Map<string, string>): string[] {
  const found: string[] = [];
  for (const dir of ["mini/js", "mini/js/page"]) {
    const at = path.join(root, dir);
    if (!fs.existsSync(at)) continue;
    for (const entry of fs.readdirSync(at, { withFileTypes: true })) {
      const file = `${dir}/${entry.name}`;
      if (entry.isFile() && entry.name.endsWith(".js") && !outputs.has(file)) found.push(file);
    }
  }
  return found.sort();
}
